// Refresh the generated files in src/firmware/esp32cam_test/ after retraining:
//   node tools/gen-esp32cam.cjs
// Arduino builds a sketch from its own folder only, so the model header is
// copied in, and the golden test vectors are converted to C arrays.
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const FW = path.join(ROOT, 'src', 'firmware');
const SKETCH = path.join(FW, 'esp32cam_test');
const PREPROCESS_CASES = 8; // keeps the sketch well inside the default app partition

const bytes = (b64) => Buffer.from(b64, 'base64');
const rows = (buf, signed, per = 24) => {
  const vals = Array.from(buf, (b) => (signed && b > 127 ? b - 256 : b));
  const out = [];
  for (let i = 0; i < vals.length; i += per) out.push('    ' + vals.slice(i, i + per).join(', ') + ',');
  return out.join('\n');
};

for (const f of ['digit_model_types.h', 'digit_model_int8.h']) {
  fs.copyFileSync(path.join(FW, f), path.join(SKETCH, f));
}

const golden = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/test/fixtures/golden.json'), 'utf8'));
const pre = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/test/fixtures/preprocess.json'), 'utf8')).cases.slice(0, PREPROCESS_CASES);
const n = golden.inputs.length;
const inLen = bytes(golden.inputs[0]).length;
const outLen = golden.logits[0].length;
const { w: pw, h: ph } = pre[0];
if (!pre.every((c) => c.w === pw && c.h === ph)) throw new Error('preprocess cases must share one crop size');

const lines = [
  '// GENERATED by tools/gen-esp32cam.cjs from tools/test/fixtures. Do not edit.',
  '// Golden vectors: int8 model inputs and the int8 logits TFLite reference kernels produce for them.',
  '#pragma once',
  '#include <stdint.h>',
  '',
  `#define GOLDEN_N ${n}`,
  `#define GOLDEN_IN_LEN ${inLen}`,
  `#define GOLDEN_OUT_LEN ${outLen}`,
  `#define PRE_N ${pre.length}`,
  `#define PRE_W ${pw}`,
  `#define PRE_H ${ph}`,
  '',
  `static const int8_t GOLDEN_INPUTS[GOLDEN_N][GOLDEN_IN_LEN] = {`,
  ...golden.inputs.map((b) => `  {\n${rows(bytes(b), true)}\n  },`),
  '};',
  '',
  `static const int8_t GOLDEN_LOGITS[GOLDEN_N][GOLDEN_OUT_LEN] = {`,
  ...golden.logits.map((l) => `  {${l.join(', ')}},`),
  '};',
  '',
  `static const uint8_t GOLDEN_LABELS[GOLDEN_N] = {${golden.labels.join(', ')}};`,
  '',
  '// Preprocessing: raw grayscale crops and the 24x32 output of src/model/preprocess.py.',
  `static const uint8_t PRE_SRC[PRE_N][PRE_W * PRE_H] = {`,
  ...pre.map((c) => `  {\n${rows(bytes(c.src), false, 40)}\n  },`),
  '};',
  '',
  `static const uint8_t PRE_EXPECTED[PRE_N][GOLDEN_IN_LEN] = {`,
  ...pre.map((c) => `  {\n${rows(bytes(c.expected), false)}\n  },`),
  '};',
  '',
];
fs.writeFileSync(path.join(SKETCH, 'golden_vectors.h'), lines.join('\n'));
console.log(`wrote ${path.relative(ROOT, SKETCH)}: model header, ${n} golden vectors, ${pre.length} preprocessing cases`);
